$identity=[Security.Principal.WindowsIdentity]::GetCurrent()
$culture=Get-Culture;$ui=Get-UICulture;$override=Get-WinUILanguageOverride;$homeLocationInfo=Get-WinHomeLocation
[ordered]@{Scope='CollectorAccount';UserSid=$identity.User.Value;UserName=$identity.Name;CultureName=$culture.Name;Lcid=$culture.LCID;EnglishName=$culture.EnglishName;NativeName=$culture.NativeName;EffectiveProcessUiCulture=$ui.Name;InstalledUiCulture=[Globalization.CultureInfo]::InstalledUICulture.Name;ConfiguredUiLanguageOverride=$override.Name;HomeGeoId=$homeLocationInfo.GeoId;HomeLocation=$homeLocationInfo.HomeLocation;ShortDatePattern=$culture.DateTimeFormat.ShortDatePattern;LongDatePattern=$culture.DateTimeFormat.LongDatePattern;ShortTimePattern=$culture.DateTimeFormat.ShortTimePattern;LongTimePattern=$culture.DateTimeFormat.LongTimePattern;FirstDayOfWeek=[string]$culture.DateTimeFormat.FirstDayOfWeek;DecimalSeparator=$culture.NumberFormat.NumberDecimalSeparator;ThousandsSeparator=$culture.NumberFormat.NumberGroupSeparator;CurrencySymbol=$culture.NumberFormat.CurrencySymbol}
